        n=tuple(sorted((x-r0,y-c0) for x,y in cells))
        # symmetry: does norm equal any 4-dir mirror?
        def mirrors(nm):
            hgt=max(x for x,_ in nm)+1; wid=max(y for _,y in nm)+1
            res=set()
            for s in nm:
                res.add(tuple(s)); res.add(tuple(reversed(s)))
                rs=[(r,c) for r,c in nm]; 
                rot=[(c,hgt-1-r) for r,c in nm]; 
                res.add(tuple(rot)); res.add(tuple(reversed(rot)))
                refl=[(r,c) for r,c in nm]; 
                res.add(tuple(refl)); res.add(tuple((c,hgt-1-r) for r,c in nm))
            return res
        mm=mirrors(n)
        sym = n in mm
        info.append({'color':c,'size':size,'bbox':(r0,r1,c0,c1),'norm':n,'sym':sym})
